<?php
require_once __DIR__ . '/../includes/auth-check.php'; require_role('vendor');
$salonStmt=db()->prepare('SELECT * FROM salons WHERE vendor_id=? LIMIT 1'); $salonStmt->execute([current_user()['id']]); $salon=$salonStmt->fetch();
if(!$salon){flash('error','Your salon profile is not ready yet.');redirect('index.php');}
$baseWhere='FROM appointments a WHERE a.salon_id=?'; $totalStmt=db()->prepare("SELECT COUNT(*) $baseWhere"); $totalStmt->execute([$salon['id']]); $total=$totalStmt->fetchColumn(); $todayStmt=db()->prepare("SELECT COUNT(*) $baseWhere AND appointment_date=CURDATE()"); $todayStmt->execute([$salon['id']]); $today=$todayStmt->fetchColumn(); $revenueStmt=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM appointments WHERE salon_id=? AND status='completed' AND MONTH(appointment_date)=MONTH(CURDATE()) AND YEAR(appointment_date)=YEAR(CURDATE())"); $revenueStmt->execute([$salon['id']]); $revenue=$revenueStmt->fetchColumn(); $recent=db()->prepare("SELECT a.*,u.name customer_name,sv.name service_name,st.name staff_name FROM appointments a JOIN users u ON u.id=a.customer_id JOIN services sv ON sv.id=a.service_id JOIN staff st ON st.id=a.staff_id WHERE a.salon_id=? ORDER BY a.appointment_date DESC,a.start_time DESC LIMIT 8"); $recent->execute([$salon['id']]); $appointments=$recent->fetchAll(); $page_title='Vendor dashboard'; include __DIR__.'/../includes/header.php';
?><main class="dashboard-shell"><div class="container"><div class="d-flex justify-content-between align-items-end mb-5"><div><div class="section-label">Partner studio</div><h1 class="display-5 mb-1"><?= e($salon['name']) ?></h1><p class="muted mb-0">Your studio at a glance.</p></div><a class="btn btn-brand" href="<?= e(url('salon.php?slug='.$salon['slug'])) ?>" target="_blank">View public profile <i class="bi bi-box-arrow-up-right ms-2"></i></a></div><div class="row g-3 mb-5"><div class="col-md-4"><div class="stat-card"><span class="muted small">Monthly revenue</span><div class="stat-number"><?= money($revenue) ?></div></div></div><div class="col-md-4"><div class="stat-card"><span class="muted small">Total bookings</span><div class="stat-number"><?= e($total) ?></div></div></div><div class="col-md-4"><div class="stat-card"><span class="muted small">Today's appointments</span><div class="stat-number"><?= e($today) ?></div></div></div></div><div class="dashboard-card p-3 p-md-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><div class="section-label">The day book</div><h2 class="h3 mb-0">Recent appointments</h2></div><span class="pill">Live</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Customer</th><th>Service</th><th>Specialist</th><th>When</th><th>Status</th></tr></thead><tbody><?php foreach($appointments as $item): ?><tr><td><strong><?= e($item['customer_name']) ?></strong><small class="d-block muted"><?= e($item['booking_code']) ?></small></td><td><?= e($item['service_name']) ?></td><td><?= e($item['staff_name']) ?></td><td><?= date('d M',strtotime($item['appointment_date'])) ?><small class="d-block muted"><?= date('g:i A',strtotime($item['start_time'])) ?></small></td><td><span class="pill"><?= e(ucfirst($item['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div></main><?php include __DIR__.'/../includes/footer.php'; ?>
